

#![allow(non_camel_case_types)]
#![allow(non_upper_case_globals)]
#![allow(non_snake_case)]

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ContextReference(pub u16, pub u16);

#[derive(Debug, Clone, Copy)]
pub enum Action {
	Pop,
	Push(&'static [ContextReference]),
	Set(&'static [ContextReference])
}

#[derive(Debug, Clone, Copy)]
pub struct _Match {
	pub pattern: &'static str, /* onigumara regex pattern, possibly with subgroups () */
	pub scope: Option<&'static [&'static str]>, /* single scope (one element) or multiple-scope capture by subgroup */
	pub action: Option<Action>,
}

#[derive(Debug, Clone, Copy)]
pub enum ClearAction { Some(u16), All, None }

#[derive(Debug, Clone, Copy)]
pub enum Rule { Include(ContextReference), Match(_Match) }

#[derive(Debug, Clone, Copy)]
pub struct ContextInfo {
	pub meta_scope: Option<&'static str>,
	pub meta_content_scope: Option<&'static str>,
	pub meta_include_prototype: bool,
	pub clear_scopes: ClearAction,
	pub rules: &'static [Rule],
}

#[derive(Debug, Clone, Copy)]
pub struct SyntaxInfo {
	pub name: &'static str,
	pub scope: &'static str,
	pub extensions: &'static [&'static str],
}


