#[inline]
pub fn get_syntax_info(id: u16) -> &'static SyntaxInfo {
	&SYNTAXES[id as usize]
}

use std::path::Path;
pub fn syntax_id_for_filename(filename: &str) ->
Option<u16> {
    let ext = Path::new(filename)
        .extension()
        .and_then(|s| s.to_str())
        .map(|s| s.trim_start_matches('.'))
        .map(|s| s.to_ascii_lowercase())?;

    for (id, info) in
SYNTAXES.iter().enumerate() {
        if info.extensions.iter().any(|e|
e.eq_ignore_ascii_case(&ext)) {
            return Some(id as u16);
        }
    }
    None
}

